<script setup>import { computed, onMounted, ref } from 'vue'; import { Package, RefreshCw, Users } from 'lucide-vue-next'; import { orderService } from '../../services/orderService'; const orders = ref([]); const loading = ref(true); const error = ref(''); const updating = ref(null); const revenue = computed(() => orders.value.reduce((sum, order) => sum + Number(order.total_price || 0), 0)); const statuses = ['processing', 'shipped', 'delivered', 'cancelled']; async function load() { loading.value = true; try { orders.value = (await orderService.adminList()).data; } catch (e) { error.value = e.response?.data?.message || 'Admin access or order data is unavailable.'; } finally { loading.value = false; } } async function update(order, status) { updating.value = order.id; try { const { data } = await orderService.updateStatus(order.id, status); order.status = data.order.status; } catch (e) { error.value = e.response?.data?.message || 'Status update failed.'; } finally { updating.value = null; } } onMounted(load);</script>
<template><section class="container page-section"><div class="section-heading"><div><p class="kicker">OPERATIONS</p><h1>Admin dashboard</h1><p class="muted">A clear view of the orders your API currently exposes.</p></div><div class="admin-actions"><RouterLink class="button button-accent" to="/admin/products"><Package :size="16" /> Manage products</RouterLink><button class="button button-light" @click="load"><RefreshCw :size="16" /> Refresh</button></div></div><p v-if="error" class="form-error">{{ error }}</p><div class="stat-grid"><div class="stat-card"><Package :size="18" /><span>Orders</span><strong>{{ orders.length }}</strong></div><div class="stat-card"><Users :size="18" /><span>Customers represented</span><strong>{{ new Set(orders.map(o => o.user_id)).size }}</strong></div><div class="stat-card accent-stat"><span>Order value</span><strong>${{ revenue.toLocaleString(undefined, { maximumFractionDigits: 0 }) }}</strong></div></div><div class="admin-table"><div class="admin-table-head"><span>Order</span><span>Customer</span><span>Total</span><span>Status</span><span>Update</span></div><div v-if="loading" class="state">Loading orders...</div><div v-for="order in orders" v-else :key="order.id" class="admin-row"><span><b>#{{ order.id }}</b><small>{{ new Date(order.created_at).toLocaleDateString() }}</small></span><span>{{ order.user?.name || 'Customer' }}<small>{{ order.user?.email || '' }}</small></span><strong>${{ Number(order.total_price).toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong><span class="status-badge" :class="`status-${order.status}`">{{ order.status }}</span><select :value="order.status" :disabled="updating === order.id" @change="update(order, $event.target.value)"><option :value="order.status">{{ order.status }}</option><option v-for="status in statuses.filter(s => s !== order.status)" :key="status" :value="status">{{ status }}</option></select></div></div></section></template>
